import java.util.Locale;
import java.util.Map;

import org.eclipse.rdf4j.sail.lmdb.config.DirectAdjacencyMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;

/**
 * The three stacked execution regimes of the LMDB native engine, as a switchable configuration.
 *
 * <p>
 * The regimes are a ladder: each one adds exactly one tier on top of the previous one, so a per-query comparison across
 * the three isolates the contribution of that tier.
 *
 * <ul>
 * <li>{@link #LMDB} — every operator reads LMDB B+-tree index cursors. The in-memory adjacency index is not built
 * ({@link DirectAdjacencyMode#DISABLED}) and runtime code generation is off.</li>
 * <li>{@link #ADJACENCY} — the in-memory adjacency index is built and preferred ({@link DirectAdjacencyMode#PREFER}),
 * runtime code generation is still off, so the interpreted operators read planes instead of cursors.</li>
 * <li>{@link #JANINO} — adjacency is preferred and hot shapes additionally compile to fused Janino kernels.</li>
 * </ul>
 *
 * <p>
 * Regime selection mutates JVM-wide system properties, so a single JVM can only ever measure one regime honestly: once
 * a kernel is compiled or an adjacency plane is built, flipping the switches does not undo it.
 * {@link #pin(ThreeTierRegime)} enforces that by failing fast on the second, differing selection. Run one JVM (or one
 * JMH fork) per regime.
 */
public enum ThreeTierRegime {

	LMDB(DirectAdjacencyMode.DISABLED, false),
	ADJACENCY(DirectAdjacencyMode.PREFER, false),
	JANINO(DirectAdjacencyMode.PREFER, true);

	static final String NATIVE_ENGINE_PROPERTY = "rdf4j.lmdb.nativeQueryEngine.enabled";
	static final String JANINO_ENABLED_PROPERTY = "rdf4j.lmdb.janinoCodegen.enabled";
	static final String JANINO_THRESHOLD_ROWS_PROPERTY = "rdf4j.lmdb.janinoCodegen.thresholdRows";

	private static final Object PIN_LOCK = new Object();
	private static ThreeTierRegime pinned;

	private final DirectAdjacencyMode adjacencyMode;
	private final boolean janinoEnabled;

	ThreeTierRegime(DirectAdjacencyMode adjacencyMode, boolean janinoEnabled) {
		this.adjacencyMode = adjacencyMode;
		this.janinoEnabled = janinoEnabled;
	}

	public static ThreeTierRegime parse(String value) {
		return valueOf(value.trim().toUpperCase(Locale.ROOT));
	}

	public String paramValue() {
		return name().toLowerCase(Locale.ROOT);
	}

	public DirectAdjacencyMode adjacencyMode() {
		return adjacencyMode;
	}

	public boolean janinoEnabled() {
		return janinoEnabled;
	}

	/**
	 * Pins this JVM to one regime and applies its system properties. Idempotent for the same regime; throws when a
	 * different regime was already applied, because the earlier regime's compiled kernels and built planes survive the
	 * property flip and would silently contaminate the measurement.
	 */
	public static void pin(ThreeTierRegime regime) {
		synchronized (PIN_LOCK) {
			if (pinned != null && pinned != regime) {
				throw new IllegalStateException("This JVM is already pinned to the " + pinned
						+ " regime; compiled kernels and built adjacency planes outlive a property flip, so "
						+ regime + " cannot be measured here. Use one JMH fork (or one JVM) per regime.");
			}
			pinned = regime;
			regime.applyProperties();
		}
	}

	/**
	 * Applies the regime's system properties. Kept separate from {@link #pin()} so the census can re-apply on each
	 * regime switch.
	 */
	Map<String, String> applyProperties() {
		Map<String, String> previous = new LinkedHashMap<>();
		set(previous, NATIVE_ENGINE_PROPERTY, "true");
		set(previous, ConfigUtil.DIRECT_ADJACENCY_MODE_PROPERTY, adjacencyMode.name());
		set(previous, JANINO_ENABLED_PROPERTY, Boolean.toString(janinoEnabled));
		// Admission normally waits for 32768 interpreted rows per shape, which small corpus cells never reach. The
		// Janino regime exists to measure compiled execution, so admit immediately and let the harness warm up and
		// await compilation instead of hoping a cell is large enough to qualify.
		set(previous, JANINO_THRESHOLD_ROWS_PROPERTY, janinoEnabled ? "0" : "");
		return previous;
	}

	/** Applies the regime to a store configuration. The adjacency mode is a store-config decision, not a property. */
	LmdbStoreConfig applyTo(LmdbStoreConfig config) {
		return config.setDirectAdjacencyMode(adjacencyMode);
	}

	private static void set(Map<String, String> previous, String property, String value) {
		previous.put(property, System.getProperty(property));
		if (value.isEmpty()) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}

	static void restore(Map<String, String> previous) {
		previous.forEach((property, value) -> {
			if (value == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, value);
			}
		});
	}
}
